const App: React.FC = () => {
  const [books, setBooks] = useState<BookMetadata[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [showSetup, setShowSetup] = useState<boolean>(false);

  const refreshBooks = async () => {
    const supabase = getSupabase();
    if (!supabase) {
      setShowSetup(true);
      return;
    }
    try {
      const data = await getAllMetadata();
      setBooks(data);
      setError(null);
      setShowSetup(false);
    } catch (err: any) {
      setError(err.message || 'Error');
      if (err.message?.includes('does not exist')) setShowSetup(true);
    }
  };

  useEffect(() => {
    refreshBooks();
    window.addEventListener('show-setup-guide', () => setShowSetup(true));
  }, []);

  if (showSetup) return <SetupGuide error={error || undefined} />;

  return (
    <Router>
      <div className="min-h-screen bg-black flex flex-col font-sans selection:bg-[#00c2ff] selection:text-black">
        <Routes>
          <Route path="/" element={<HomePage books={books} error={error} />} />
          <Route path="/book/:id" element={<SocialPage />} />
          <Route path="/read/:id" element={<BookViewer />} />
          <Route path="/author/:name" element={<AuthorPage />} />
        </Routes>
        <UploadModal onUploadComplete={refreshBooks} />
      </div>
    </Router>
  );
};

export default App;

import React, { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { BookMetadata } from '../types';
import { getBookMetadata } from '../services/db';
import Footer from './Footer';
import { 
  Heart, 
  Share2, 
  BookOpen, 
  ArrowLeft, 
  Check,
  Hash,
  AlertCircle,
  ShieldCheck
} from 'lucide-react';

const SocialPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const [book, setBook] = useState<BookMetadata | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);
  const [liked, setLiked] = useState(false);

  useEffect(() => {
    if (id) {
      setLoading(true);
      getBookMetadata(id)
        .then(data => {
          setBook(data);
          setLoading(false);
        })
        .catch(err => {
          setError(err.message);
          setLoading(false);
        });
    }
    window.scrollTo(0, 0);
  }, [id]);

  if (loading) return (
    <div className="min-h-screen flex items-center justify-center bg-black">
      <div className="w-12 h-12 border-2 border-[#00c2ff]/20 border-t-[#00c2ff] rounded-full animate-spin" />
    </div>
  );

  if (error || !book) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-black text-white">
        <AlertCircle size={64} className="text-red-600 mb-6" />
        <h2 className="text-3xl font-black mb-2 tracking-tighter uppercase italic text-red-600">Archive_Corrupted</h2>
        <Link to="/" className="text-[#00c2ff] font-bold underline underline-offset-8 uppercase tracking-widest text-xs">Return_To_Nexus</Link>
      </div>
    );
  }

  const copyUrl = () => {
    navigator.clipboard.writeText(window.location.href);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="min-h-screen bg-black text-white selection:bg-[#00c2ff] selection:text-black">
      {/* Non-overlapping Header */}
      <div className="max-w-[1600px] mx-auto p-6 flex justify-between items-center relative z-10">
        <Link to="/" className="bg-[#0a0f14] p-3 rounded-2xl border border-white/5 hover:bg-[#111] transition-all flex items-center gap-3">
          <ArrowLeft size={20} />
          <span className="text-[10px] font-black uppercase tracking-widest hidden sm:inline">Return to Archives</span>
        </Link>
        <button onClick={copyUrl} className="bg-[#00c2ff] text-black px-6 py-3 rounded-2xl font-black flex items-center gap-3 hover:brightness-110 transition-all shadow-[0_0_20px_rgba(0,194,255,0.2)]">
          {copied ? <Check size={18} /> : <Hash size={18} />}
          <span className="text-[10px] uppercase tracking-widest">{copied ? 'Synced' : 'Link Hash'}</span>
        </button>
      </div>

      <main className="max-w-6xl mx-auto px-6 py-12 md:py-24 grid md:grid-cols-2 gap-12 lg:gap-20 items-center mb-24">
        {/* Book Artwork Container - NO CUT OFF */}
        <div className="relative group">
          <div className="aspect-[3/4] rounded-3xl overflow-hidden shadow-[0_0_100px_rgba(0,194,255,0.05)] border border-white/10 bg-[#0a0a0a] flex items-center justify-center relative">
            {/* Backdrop Glow */}
            <img 
              src={book.thumbnail} 
              className="absolute inset-0 w-full h-full object-cover blur-3xl opacity-20"
              aria-hidden="true"
            />
            {/* Full Image Display */}
            <img 
              src={book.thumbnail} 
              alt={book.title} 
              className="relative z-10 max-w-full max-h-full object-contain grayscale group-hover:grayscale-0 transition-all duration-700 p-8 md:p-12 scale-100 group-hover:scale-[1.02]" 
            />
          </div>

          <div className="mt-8 flex justify-center gap-12">
            <button onClick={() => setLiked(!liked)} className={`flex flex-col items-center gap-2 transition-all ${liked ? 'text-[#00c2ff]' : 'text-slate-600 hover:text-white'}`}>
              <Heart size={32} fill={liked ? 'currentColor' : 'none'} className={liked ? 'shadow-[0_0_20px_rgba(0,194,255,0.4)]' : ''} />
              <span className="text-[10px] font-black uppercase tracking-[0.3em]">Synapse_Like</span>
            </button>
            <button onClick={copyUrl} className="flex flex-col items-center gap-2 text-slate-600 hover:text-white transition-all">
              <Share2 size={32} />
              <span className="text-[10px] font-black uppercase tracking-[0.3em]">Network_Sync</span>
            </button>
          </div>
        </div>

        {/* Content Details */}
        <div className="space-y-10">
          <div>
            <div className="inline-flex items-center gap-3 px-4 py-1 bg-[#00c2ff]/10 border border-[#00c2ff]/20 rounded-md mb-6">
              <div className="w-1.5 h-1.5 rounded-full bg-[#00c2ff] animate-pulse" />
              <span className="text-[10px] font-black text-[#00c2ff] tracking-[0.4em] uppercase">
                {book.genre}
              </span>
            </div>
            <h1 className="text-5xl lg:text-7xl font-black leading-none mb-4 tracking-tighter italic uppercase text-white">{book.title}</h1>
            <Link to={`/author/${encodeURIComponent(book.author)}`}>
              <p className="text-slate-500 font-bold text-xl lg:text-2xl uppercase tracking-[0.1em] opacity-80 italic hover:text-[#00c2ff] transition-colors">
