              <span className="text-slate-600 uppercase tracking-[0.3em] text-[10px] font-black">Archive_Index</span>
              <span className="font-mono text-[#00c2ff] text-xs">#{book.id}</span>
            </div>
            <div className="flex justify-between items-center border-b border-white/5 pb-4">
