            </div>
          </div>

          <Link to={`/read/${book.id}`} className="w-full bg-[#00c2ff] text-black py-6 rounded-2xl font-black text-center text-xl hover:brightness-110 transition-all flex items-center justify-center gap-4 shadow-[0_0_40px_rgba(0,194,255,0.2)] uppercase tracking-tighter italic">
            <BookOpen size={28} />
            Initialize Archive Site
          </Link>
        </div>
      </main>

      <Footer />
    </div>
  );
};

export default SocialPage;

