const CATEGORIES = [
  "COMEDY", "DETECTIVE", "SCI-FI", "FANTASY", 
  "HORROR", "APOCALYPSE", "ACTION", "DRAMA"
];

const SetupGuide: React.FC<{ error?: string }> = ({ error }) => {
  const [copied, setCopied] = useState(false);
  const sqlCode = `-- Run this in Supabase SQL Editor:
CREATE TABLE IF NOT EXISTS bookz (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  author TEXT NOT NULL,
  genre TEXT NOT NULL,
  pages INTEGER NOT NULL,
  thumbnail TEXT NOT NULL,
  upload_date TIMESTAMPTZ DEFAULT NOW()
);
ALTER TABLE bookz ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public Read" ON bookz FOR SELECT USING (true);
CREATE POLICY "Public Insert" ON bookz FOR INSERT WITH CHECK (true);`;

  const copySql = () => {
    navigator.clipboard.writeText(sqlCode);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="min-h-screen bg-black flex items-center justify-center p-6">
      <div className="max-w-3xl w-full bg-[#0a0a0a] rounded-3xl border border-white/10 p-12">
        <h1 className="text-2xl font-black text-white uppercase mb-8">System Setup</h1>
        {error && <div className="bg-red-950/30 p-4 border border-red-900/50 text-red-500 text-xs mb-8">{error}</div>}
        <button onClick={copySql} className="text-[#00c2ff] text-xs font-bold uppercase tracking-widest mb-4 flex items-center gap-2">
          {copied ? <Check size={14} /> : <Copy size={14} />} Copy SQL Code
        </button>
        <pre className="bg-black/50 p-6 rounded-xl border border-white/5 text-[10px] text-indigo-400 overflow-x-auto mb-8">{sqlCode}</pre>
        <button onClick={() => window.location.reload()} className="w-full bg-[#00c2ff] text-black py-4 rounded-xl font-black uppercase tracking-widest text-sm">Initialize Database</button>
      </div>
    </div>
  );
};

const HomePage: React.FC<{ books: BookMetadata[], error: string | null, searchQuery: string, setSearchQuery: (q: string) => void }> = ({ books, error, searchQuery, setSearchQuery }) => {
  const filteredBooks = useMemo(() => {
    const q = searchQuery.toLowerCase().trim();
    if (!q) return books;
    return books.filter(b => 
      b.title.toLowerCase().includes(q) || 
      b.author.toLowerCase().includes(q) || 
      b.genre.toLowerCase().includes(q)
    );
  }, [books, searchQuery]);

  return (
    <div className="min-h-screen bg-black text-white">
      <Navbar searchQuery={searchQuery} setSearchQuery={setSearchQuery} />
      <Walkthrough />

      <div className="pt-24">
        <section className="max-w-[1600px] mx-auto px-6 py-10">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-6">
            {filteredBooks.slice(0, 5).map((book) => (
              <BookCard key={book.id} book={book} />
            ))}
          </div>
        </section>

        <div className="bg-black border-y border-white/5 py-4">
          <div className="max-w-[1600px] mx-auto px-6 flex items-center gap-10 overflow-x-auto no-scrollbar">
            <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest shrink-0 border-r border-white/10 pr-6">CATEGORIES:</span>
            {CATEGORIES.map(cat => (
              <button 
                key={cat} 
                onClick={() => setSearchQuery(cat === searchQuery ? "" : cat)}
                className={`text-[10px] font-black uppercase tracking-[0.2em] transition-all whitespace-nowrap ${searchQuery === cat ? 'text-[#00c2ff]' : 'text-slate-400 hover:text-[#00c2ff]'}`}
              >
                {cat}
              </button>
            ))}
          </div>
        </div>

        <section className="py-24 px-4 text-center">
          <div className="max-w-6xl mx-auto">
            <h1 className="text-[8vw] font-black tracking-tighter leading-none italic uppercase text-white">
              Zetsumetsu <span className="text-[#00c2ff]">EOe</span> Books
            </h1>
            <div className="flex items-center justify-center gap-6 mt-6">
              <div className="h-[1px] w-32 bg-white/10" />
              <span className={`text-[12px] font-black uppercase tracking-[1em] ${searchQuery ? 'text-[#00c2ff]' : 'text-slate-600'}`}>
                {searchQuery ? 'Searching Archive' : 'Digital Book Archive'}
              </span>
              <div className="h-[1px] w-32 bg-white/10" />
            </div>
          </div>
        </section>

        <section className="max-w-[1600px] mx-auto px-6 pb-40">
          <div className="flex items-center gap-6 mb-12">
            <span className="text-[11px] font-black uppercase tracking-[0.5em] text-[#00c2ff]">BOOK LIST</span>
            <div className="h-[1px] flex-1 bg-white/10" />
            <span className="text-[11px] font-black text-slate-600 uppercase tracking-widest">{filteredBooks.length} ITEMS</span>
          </div>

          {error ? (
            <div className="text-center py-40">
              <AlertCircle className="mx-auto text-red-500 mb-4" />
              <h3 className="text-xl font-black uppercase">Database Error</h3>
              <p className="text-slate-500 text-xs mt-2 uppercase">{error}</p>
            </div>
          ) : filteredBooks.length === 0 ? (
            <div className="text-center py-40 border border-white/5 rounded-3xl bg-[#050505]">
              <Search className="mx-auto text-slate-800 mb-6" size={64} />
              <h3 className="text-2xl font-black uppercase opacity-20">No books found</h3>
              <button onClick={() => setSearchQuery("")} className="mt-6 text-[10px] font-black text-[#00c2ff] uppercase underline">Clear Search</button>
            </div>
          ) : (
            <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 xl:grid-cols-8 gap-x-8 gap-y-12">
              {filteredBooks.map((book) => (
                <div key={book.id} className="group">
                  <Link to={`/book/${book.id}`}>
                    <div className="aspect-[3/4] rounded-2xl overflow-hidden bg-[#0a0a0a] border border-white/5 mb-4 group-hover:border-[#00c2ff]/40 transition-all flex items-center justify-center">
                      <img src={book.thumbnail} className="max-w-full max-h-full object-contain group-hover:scale-105 transition-transform" alt={book.title} />
                    </div>
                    <h4 className="text-[11px] font-black uppercase text-white/80 truncate mb-1 group-hover:text-[#00c2ff]">{book.title}</h4>
                    <p className="text-[8px] font-bold text-slate-600 uppercase tracking-widest">{book.pages} Pages</p>
                  </Link>
                </div>
              ))}
            </div>
          )}
        </section>
        <Footer />
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [books, setBooks] = useState<BookMetadata[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [showSetup, setShowSetup] = useState<boolean>(false);
  const [searchQuery, setSearchQuery] = useState<string>("");

  const refreshBooks = async () => {
    const supabase = getSupabase();
    if (!supabase) {
      setShowSetup(true);
      return;
    }
    try {
      const data = await getAllMetadata();
      setBooks(data);
      setError(null);
      setShowSetup(false);
    } catch (err: any) {
      setError(err.message || 'Error');
      if (err.message?.includes('does not exist')) setShowSetup(true);
    }
  };

  useEffect(() => {
    refreshBooks();
    window.addEventListener('show-setup-guide', () => setShowSetup(true));
  }, []);

  if (showSetup) return <SetupGuide error={error || undefined} />;

  return (
    <Router>
      <div className="min-h-screen bg-black flex flex-col font-sans">
        <Routes>
          <Route path="/" element={<HomePage books={books} error={error} searchQuery={searchQuery} setSearchQuery={setSearchQuery} />} />
          <Route path="/book/:id" element={<SocialPage />} />
          <Route path="/read/:id" element={<BookViewer />} />
          <Route path="/author/:name" element={<AuthorPage />} />
        </Routes>
        <UploadModal onUploadComplete={refreshBooks} />
      </div>
    </Router>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { X, Upload, CheckCircle, AlertCircle, FileText } from 'lucide-react';
import { processPdfForStore } from '../services/pdfService';
import { saveBook } from '../services/db';
import { BookMetadata, BookData } from '../types';

interface UploadModalProps {
  onUploadComplete: () => void;
}

const UploadModal: React.FC<UploadModalProps> = ({ onUploadComplete }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [status, setStatus] = useState<'idle' | 'processing' | 'uploading' | 'success' | 'error'>('idle');
  const [errorMessage, setErrorMessage] = useState('');
  const [pdfInfo, setPdfInfo] = useState<any>(null);
  const [formData, setFormData] = useState({ title: '', author: '', genre: 'General' });
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleOpen = () => { setIsOpen(true); setStatus('idle'); setPdfInfo(null); setErrorMessage(''); };
    window.addEventListener('open-upload-modal', handleOpen);
    return () => window.removeEventListener('open-upload-modal', handleOpen);
  }, []);

  const handleFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setStatus('processing');
    try {
      const info = await processPdfForStore(file);
      setPdfInfo(info);
      setFormData(prev => ({ ...prev, title: file.name.replace('.pdf', '') }));
      setStatus('idle');
    } catch (err) { setStatus('error'); setErrorMessage('Failed to process PDF.'); }
  };

  const publish = async () => {
    if (!pdfInfo) return;
    setStatus('uploading');
    try {
      const id = crypto.randomUUID().split('-')[0];
      const metadata: BookMetadata = { id, thumbnail: pdfInfo.thumbnail, title: formData.title, author: formData.author, genre: formData.genre, pages: pdfInfo.pageCount, uploadDate: Date.now() };
      const data: BookData = { id, pdfData: pdfInfo.pdfData };
      await saveBook(metadata, data);
      setStatus('success');
      onUploadComplete();
    } catch (err: any) { setStatus('error'); setErrorMessage(err.message || 'Upload failed.'); }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/90" onClick={() => setIsOpen(false)} />
      <div className="relative bg-[#0a0a0a] w-full max-w-xl rounded-3xl overflow-hidden border border-white/10">
        <div className="p-10">
          <div className="flex justify-between items-center mb-8">
            <h2 className="text-2xl font-black text-white uppercase">Upload PDF</h2>
            <button onClick={() => setIsOpen(false)} className="text-slate-500"><X size={24} /></button>
          </div>

          {status === 'error' ? (
            <div className="py-12 text-center">
              <AlertCircle size={64} className="text-red-600 mx-auto mb-6" />
              <h3 className="text-2xl font-black text-white uppercase">Upload Error</h3>
              <p className="text-slate-500 mb-8">{errorMessage}</p>
              <button onClick={() => setStatus('idle')} className="w-full bg-white text-black py-4 rounded-xl font-black uppercase">Retry</button>
            </div>
          ) : status === 'success' ? (
            <div className="py-12 text-center">
              <CheckCircle size={64} className="text-[#00c2ff] mx-auto mb-6" />
              <h3 className="text-2xl font-black text-white uppercase">Upload Successful</h3>
              <p className="text-slate-500 mb-8">Your book has been saved to the library.</p>
              <button onClick={() => setIsOpen(false)} className="w-full bg-[#00c2ff] text-black py-4 rounded-xl font-black uppercase">Close</button>
            </div>
          ) : status === 'uploading' ? (
            <div className="py-20 text-center">
              <div className="w-16 h-16 border-2 border-t-[#00c2ff] rounded-full animate-spin mx-auto mb-8" />
              <p className="text-xl font-black text-white uppercase">Saving book...</p>
            </div>
          ) : !pdfInfo ? (
            <div 
              onClick={() => fileInputRef.current?.click()}
              className="border-2 border-dashed border-white/10 rounded-3xl p-24 text-center cursor-pointer hover:border-[#00c2ff]/50"
            >
              <input type="file" ref={fileInputRef} className="hidden" accept=".pdf" onChange={handleFile} />
              <FileText size={48} className="mx-auto mb-4 text-slate-700" />
              <p className="font-black text-white uppercase">Select PDF File</p>
            </div>
          ) : (
            <div className="space-y-6">
              <div className="flex gap-6 p-6 bg-black rounded-2xl border border-white/5 items-center">
                <img src={pdfInfo.thumbnail} className="w-20 aspect-[3/4] object-cover rounded-lg" alt="thumb" />
                <p className="text-lg font-black text-white uppercase truncate">{formData.title}</p>
              </div>
              <input value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} placeholder="Book Title" className="w-full bg-black border border-white/10 py-4 px-6 rounded-xl text-white uppercase" />
              <input value={formData.author} onChange={e => setFormData({...formData, author: e.target.value})} placeholder="Author Name" className="w-full bg-black border border-white/10 py-4 px-6 rounded-xl text-white uppercase" />
              <button onClick={publish} className="w-full bg-[#00c2ff] text-black py-4 rounded-xl font-black uppercase">Publish Book</button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default UploadModal;

import React, { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { BookMetadata } from '../types';
import { getBookMetadata } from '../services/db';
import Footer from './Footer';
import { 
  Heart, 
  Share2, 
  BookOpen, 
  ArrowLeft, 
  Check,
  Link as LinkIcon,
  AlertCircle
} from 'lucide-react';

const SocialPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const [book, setBook] = useState<BookMetadata | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);
  const [liked, setLiked] = useState(false);

  useEffect(() => {
    if (id) {
      setLoading(true);
      getBookMetadata(id)
        .then(data => {
          setBook(data);
          setLoading(false);
        })
        .catch(err => {
          setError(err.message);
          setLoading(false);
        });
    }
    window.scrollTo(0, 0);
  }, [id]);

  if (loading) return (
    <div className="min-h-screen flex items-center justify-center bg-black">
      <div className="w-12 h-12 border-2 border-t-[#00c2ff] rounded-full animate-spin" />
    </div>
  );

  if (error || !book) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-black text-white">
        <AlertCircle size={64} className="text-red-600 mb-6" />
        <h2 className="text-2xl font-black mb-4 uppercase">Book Not Found</h2>
        <Link to="/" className="text-[#00c2ff] font-bold underline uppercase">Return Home</Link>
      </div>
    );
  }

  const copyUrl = () => {
    navigator.clipboard.writeText(window.location.href);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="min-h-screen bg-black text-white">
      <div className="max-w-[1600px] mx-auto p-6 flex justify-between items-center">
        <Link to="/" className="p-3 bg-white/5 rounded-xl border border-white/5 hover:bg-white/10 transition-all flex items-center gap-2">
          <ArrowLeft size={18} />
          <span className="text-[10px] font-black uppercase tracking-widest">Back</span>
        </Link>
