              <h3 className="text-2xl font-black text-white uppercase">Error</h3>
              <p className="text-slate-500 mb-8 font-mono text-[10px]">{errorMessage}</p>
              <button onClick={() => setStatus('idle')} className="w-full bg-white text-black py-4 rounded-xl font-black uppercase tracking-widest">Retry</button>
