              <input value={formData.author} onChange={e => setFormData({...formData, author: e.target.value})} placeholder="Author" className="w-full bg-black border border-white/10 py-4 px-6 rounded-xl text-white uppercase font-black text-xs focus:border-[#00c2ff]/50 outline-none" />
