import React, { useEffect, useState, useRef } from 'react';
import { useParams, Link } from 'react-router-dom';
import { BookMetadata, BookData } from '../types';
import { renderPdfPage } from '../services/pdfService';
import { getBookMetadata, getBookData } from '../services/db';
import { 
  ChevronUp, 
  ChevronDown, 
  X, 
  Share2, 
  Check, 
  Play, 
  Pause, 
  Tv,
  Globe
} from 'lucide-react';

const SPEEDS = {
  AMBIENT: 15000,
  STANDARD: 8000,
  RAPID: 4000
};

const BookViewer: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const [metadata, setMetadata] = useState<BookMetadata | null>(null);
  const [pdfData, setPdfData] = useState<BookData | null>(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [loading, setLoading] = useState(true);
  const [copied, setCopied] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [playSpeed, setPlaySpeed] = useState<keyof typeof SPEEDS>('STANDARD');
  const [progress, setProgress] = useState(0);
  const [uiVisible, setUiVisible] = useState(true);
  const [isTransitioning, setIsTransitioning] = useState(false);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const uiTimeoutRef = useRef<number | null>(null);

  useEffect(() => {
    if (id) {
      Promise.all([getBookMetadata(id), getBookData(id)]).then(([meta, data]) => {
        setMetadata(meta);
        setPdfData(data);
        setLoading(false);
      });
    }
  }, [id]);

  useEffect(() => {
    if (pdfData && canvasRef.current) {
      setIsTransitioning(true);
      const timer = setTimeout(() => {
        renderPdfPage(pdfData.pdfData, currentPage, canvasRef.current!).then(() => {
          setIsTransitioning(false);
        });
      }, 300);
      return () => clearTimeout(timer);
    }
  }, [pdfData, currentPage]);

  useEffect(() => {
    let interval: number;
    let progressInterval: number;
    if (isPlaying && metadata) {
      const startTime = Date.now();
      const duration = SPEEDS[playSpeed];
      progressInterval = window.setInterval(() => {
        const elapsed = Date.now() - startTime;
        setProgress(Math.min((elapsed / duration) * 100, 100));
      }, 50);
      interval = window.setInterval(() => {
        setCurrentPage(prev => (prev >= metadata.pages ? (setIsPlaying(false), prev) : prev + 1));
        setProgress(0);
      }, duration);
    } else {
      setProgress(0);
    }
    return () => { clearInterval(interval); clearInterval(progressInterval); };
  }, [isPlaying, playSpeed, metadata, currentPage]);

  useEffect(() => {
    const showUI = () => {
      setUiVisible(true);
      if (uiTimeoutRef.current) window.clearTimeout(uiTimeoutRef.current);
      if (isPlaying) uiTimeoutRef.current = window.setTimeout(() => setUiVisible(false), 3000);
    };
    window.addEventListener('mousemove', showUI);
    window.addEventListener('touchstart', showUI);
    return () => { window.removeEventListener('mousemove', showUI); window.removeEventListener('touchstart', showUI); };
  }, [isPlaying]);

  const copyAuthorUrl = () => {
    if (!metadata) return;
    const baseUrl = window.location.href.split('#')[0];
    const authorUrl = `${baseUrl}#/author/${encodeURIComponent(metadata.author)}`;
    navigator.clipboard.writeText(authorUrl);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  if (loading) return (
    <div className="h-screen flex items-center justify-center bg-black">
      <div className="w-12 h-12 border-2 border-[#00c2ff]/20 border-t-[#00c2ff] rounded-full animate-spin" />
    </div>
  );

  if (!metadata || !pdfData) return (
    <div className="h-screen flex items-center justify-center bg-black text-white">
      <Link to="/" className="bg-[#00c2ff] text-black px-6 py-2 rounded-full font-black uppercase text-[10px] tracking-widest">Return to Archives</Link>
    </div>
  );

  return (
    <div className={`h-screen w-screen bg-black text-white overflow-hidden flex transition-all duration-700 ${!uiVisible ? 'cursor-none' : ''}`}>

      {/* 1. Global Progress Bar (Cyan Shadow) */}
      <div className="fixed top-0 left-0 right-0 z-50 h-[2px] bg-white/5">
        <div 
          className="h-full bg-[#00c2ff] transition-all duration-100 linear shadow-[0_0_15px_rgba(0,194,255,1)]"
          style={{ width: `${progress}%` }}
        />
      </div>

      {/* 2. Side Control (Right Gutter) */}
      <aside className={`fixed right-6 top-1/2 -translate-y-1/2 z-50 flex flex-col gap-4 transition-all duration-500 transform ${uiVisible ? 'translate-x-0 opacity-100' : 'translate-x-20 opacity-0'}`}>
        <div className="bg-[#0a0f14] border border-white/10 p-2 rounded-3xl shadow-[0_20px_40px_rgba(0,0,0,0.8)] flex flex-col items-center gap-3">
          <button 
            onClick={() => setIsPlaying(!isPlaying)}
            className={`w-12 h-12 flex items-center justify-center rounded-2xl transition-all ${isPlaying ? 'bg-[#00c2ff] text-black' : 'hover:bg-white/5 text-slate-400'}`}
          >
            {isPlaying ? <Pause size={20} fill="currentColor" /> : <Play size={20} fill="currentColor" />}
          </button>

          <div className="w-8 h-[1px] bg-white/5" />

          <button 
            disabled={currentPage <= 1 || isPlaying} 
            onClick={() => setCurrentPage(prev => prev - 1)}
            className="w-10 h-10 flex items-center justify-center rounded-xl hover:bg-white/5 disabled:opacity-5 text-slate-500"
          >
            <ChevronUp size={24} />
          </button>

          <div className="flex flex-col items-center">
            <span className="text-[11px] font-black text-[#00c2ff] italic leading-none">{currentPage}</span>
            <span className="text-[7px] font-bold text-slate-600 uppercase tracking-widest mt-1">/ {metadata.pages}</span>
          </div>

          <button 
            disabled={currentPage >= metadata.pages || isPlaying} 
            onClick={() => setCurrentPage(prev => prev + 1)}
            className="w-10 h-10 flex items-center justify-center rounded-xl hover:bg-white/5 disabled:opacity-5 text-slate-500"
          >
            <ChevronDown size={24} />
          </button>
        </div>

        <div className="bg-[#0a0f14] border border-white/10 p-1 rounded-2xl flex flex-col items-center gap-1">
          {(['AMBIENT', 'STANDARD', 'RAPID'] as const).map((s) => (
            <button
              key={s}
              onClick={() => setPlaySpeed(s)}
              className={`w-10 h-8 rounded-xl text-[7px] font-black tracking-tighter transition-all ${playSpeed === s ? 'bg-white text-black' : 'text-slate-600 hover:text-white/10'}`}
            >
              {s[0]}
            </button>
          ))}
        </div>
      </aside>

      {/* 3. Corner Actions */}
      <div className={`fixed top-6 left-6 z-50 transition-all duration-500 ${uiVisible ? 'opacity-100' : 'opacity-0'}`}>
        <Link to={`/book/${id}`} className="flex items-center gap-4 bg-[#0a0f14] border border-white/10 p-2 pr-6 rounded-2xl hover:bg-[#111] transition-all">
          <div className="w-10 h-10 bg-white/5 rounded-xl flex items-center justify-center text-slate-400">
            <X size={20} />
          </div>
          <div className="flex flex-col">
            <span className="text-[10px] font-black uppercase tracking-widest text-[#00c2ff] leading-none mb-1">Exit Archive</span>
            <span className="text-[9px] font-mono text-slate-600 leading-none">{metadata.id}</span>
          </div>
        </Link>
      </div>

      <div className={`fixed top-6 right-6 z-50 transition-all duration-500 ${uiVisible ? 'opacity-100' : 'opacity-0'}`}>
        <button 
          onClick={copyAuthorUrl}
          className="bg-white text-black h-14 px-8 rounded-2xl flex items-center gap-3 font-black text-[10px] uppercase tracking-[0.2em] hover:bg-[#00c2ff] transition-all shadow-2xl"
        >
          {copied ? <Check size={18} /> : <Share2 size={18} />}
          <span>{copied ? 'Link Copied' : 'Author Link'}</span>
        </button>
      </div>

      {/* 4. Reading Area */}
      <main className="flex-1 h-full w-full flex items-center justify-center relative bg-[#020202]">
        <div className={`relative flex items-center justify-center transition-all duration-500 transform ${isTransitioning ? 'scale-[0.99] opacity-30' : 'scale-100 opacity-100'}`}>
           <div className="relative shadow-[0_0_150px_rgba(0,194,255,0.05)] rounded-sm overflow-hidden bg-white max-w-[85vw] max-h-[90vh]">
            <canvas 
              ref={canvasRef} 
              className="max-w-[85vw] max-h-[90vh] block object-contain"
            />
            {currentPage > 1 && (
              <div className="absolute inset-y-0 left-0 w-12 bg-gradient-to-r from-black/20 to-transparent pointer-events-none" />
            )}
          </div>
        </div>
        {/* Neon Ambient Backlight */}
        <div className="absolute inset-0 pointer-events-none -z-10 flex items-center justify-center">
           <div className={`w-[70vw] h-[70vh] bg-[#00c2ff]/5 blur-[200px] rounded-full transition-opacity duration-1000 ${isPlaying ? 'opacity-100' : 'opacity-40'}`} />
        </div>
      </main>

      <div className={`fixed bottom-6 left-6 z-50 transition-opacity duration-500 ${uiVisible ? 'opacity-50' : 'opacity-0'}`}>
        <div className="flex items-center gap-3 bg-[#0a0f14]/80 p-3 rounded-xl border border-white/5">
          <Globe size={14} className={isPlaying ? 'text-[#00c2ff] animate-pulse' : 'text-slate-600'} />
          <span className="text-[9px] font-black uppercase tracking-[0.4em] text-white">Stream: {isPlaying ? 'Live' : 'Buffered'}</span>
        </div>
      </div>
    </div>
  );
};

export default BookViewer;

